// Parse debug agent output into structured result
const agentResult = $('Debug Agent').item.json;
const output = agentResult.output || agentResult.text || '';

let diagnosis = output;
let proposed_fix = '';
let should_retry = false;
let severity = 'medium';

// Try to parse structured JSON from output
try {
  const jsonMatch = output.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    if (parsed.diagnosis) diagnosis = parsed.diagnosis;
    if (parsed.proposed_fix) proposed_fix = parsed.proposed_fix;
    if (typeof parsed.should_retry === 'boolean') should_retry = parsed.should_retry;
    if (parsed.severity) severity = parsed.severity;
  }
} catch (e) {
  // Not JSON, use raw output
}

return {
  json: {
    agent_slug: 'debug_agent',
    diagnosis,
    proposed_fix,
    should_retry,
    severity,
    passed: true
  }
};
